=You are a second-line integration-support engineer at a property-management platform. Classify the following failed integration record. Return STRICT JSON only, matching the output schema. Do not include markdown fences.

SOURCE: {{ $json.source }}
HTTP STATUS: {{ $json.http_status }}
ERROR BODY: {{ $json.error_body }}
PAYLOAD (one row from upstream ERP): {{ JSON.stringify($json.payload) }}

Rules:
- category MUST be one of: auth, validation, mapping, rate_limit, upstream_outage, duplicate, unknown.
- client_message: plain English, max 80 words, no jargon, suitable to paste into a support reply.
- confidence: your calibrated 0..1 estimate.

parameters.jsCode:
// Rule-based mock when ANTHROPIC_API_KEY is not set.
// Must produce the SAME shape as the AI Agent (so the next PATCH node is agnostic).
const j = $json;
const body = typeof j.error_body === 'string' ? j.error_body : JSON.stringify(j.error_body || '');
const status = Number(j.http_status || 0);
let category = 'unknown';
let cause = 'Could not classify from the available fields.';
let fix = 'Open the error payload and compare against docs/mapping.md.';
let msg = 'We hit a problem syncing this record; our team is looking at it.';
let confidence = 0.4;

if (status === 401 || body.includes('invalid_api_key')) {
  category = 'auth';
  cause = 'Platform rejected the X-API-Key.';
  fix = 'Rotate the API key in n8n credentials and verify it has write scope.';
  msg = 'Access to the platform was denied. The team is refreshing credentials and will retry.';
  confidence = 0.85;
} else if (status === 403 || body.includes('read_only_key')) {
  category = 'auth';
  cause = 'Read-only key used for a write endpoint.';
  fix = 'Switch the HTTP node to the write-scoped credential.';
  msg = 'A read-only credential was used for a write operation; corrected and retrying.';
  confidence = 0.9;
} else if (status === 409 || body.includes('external_id_conflict')) {
  category = 'duplicate';
  cause = 'external_id exists with a different chamber_of_commerce_id.';
  fix = 'Escalate: a human needs to confirm which KvK is correct.';
  msg = 'This tenant could not be updated because the Chamber of Commerce number on file does not match. We are checking which one is correct.';
  confidence = 0.9;
} else if (status === 422 || body.includes('"error":"validation"')) {
  category = 'validation';
  // Try to lift one specific code from the body for a sharper message.
  const m = body.match(/\"codes\":\s*\[(.*?)\]/);
  const codes = m ? m[1] : '';
  if (codes.includes('invalid_kvk')) { cause = 'KvK number is not 8 digits.'; msg = 'Chamber of Commerce number has the wrong length.'; }
  else if (codes.includes('invalid_date')) { cause = 'contract_start is not a real DD-MM-YYYY date.'; msg = 'Lease start date is not a real date.'; }
  else if (codes.includes('invalid_amount')) { cause = 'maandhuur is not a parseable number.'; msg = 'Monthly rent value could not be read as a number.'; }
  else if (codes.includes('unknown_status')) { cause = 'status is neither actief nor beeindigd.'; msg = 'Tenant status is unrecognised.'; }
  else if (codes.includes('missing_name')) { cause = 'tenant name is empty.'; msg = 'Tenant name was missing on the source record.'; }
  else { cause = 'Row failed canonical validation. See docs/mapping.md.'; }
  fix = 'Fix the source row in the ERP or add a mapping rule in WF1. Then re-run the sync.';
  confidence = 0.8;
} else if (status === 429 || body.includes('rate_limited')) {
  category = 'rate_limit';
  cause = 'Platform rate limit exceeded.';
  fix = 'Lower n8n batching or add jitter between requests.';
  msg = 'The system is sending requests slightly faster than the platform accepts; it will slow down automatically.';
  confidence = 0.9;
} else if (status >= 500 || body.includes('upstream_outage')) {
  category = 'upstream_outage';
  cause = 'Platform returned a 5xx after retries.';
  fix = 'Check platform health. Keep the row in the retry queue.';
  msg = 'The platform was temporarily unavailable; the sync will retry.';
  confidence = 0.75;
}
return [{ json: {
  id: j.id,
  triage: { category, likely_cause: cause, suggested_fix: fix, client_message: msg, confidence, model: 'rules' },
} }];

// Normalize the AI Agent output into { id, triage } shape.
const j = $json;
const parsed = j.output ?? j.result ?? j;
const id = $('Explode errors').item.json.id;
return [{ json: { id, triage: { ...parsed, model: 'claude' } } }];
